sign("5.40", "Пешеходная зона", G5, "Вводит территорию преимущественного движения пешеходов. Движение на СПМ запрещено, автомобили допускаются только в установленных случаях.", symbol="П")
sign("5.41", "Конец пешеходной зоны", G5, "Отменяет режим знака 5.40. Дальнейший маршрут определяется обычными и специальными правилами.", symbol="П")
sign("5.42", "Платная автомобильная дорога", G5, "Сообщает о начале участка с электронным сбором платы в свободном многополосном потоке. Заранее проверьте способ оплаты и категорию транспорта.", symbol="€")
sign("5.43", "Конец платной автомобильной дороги", G5, "Обозначает конец участка электронного сбора платы знака 5.42.", symbol="€")

for code, name, symbol in [
    ("6.1", "Пункт первой медицинской помощи", "+"),
    ("6.2", "Больница", "H"),
    ("6.3.1–6.3.4", "Автозаправочная станция", "F"),
    ("6.4", "Техническое обслуживание автомобилей", "🔧"),
    ("6.5", "Мойка автомобилей", "W"),
    ("6.6", "Телефон", "T"),
    ("6.7", "Пункт питания", "🍴"),
    ("6.8", "Питьевая вода", "💧"),
    ("6.9", "Гостиница или мотель", "🛏"),
    ("6.10", "Кемпинг", "⛺"),
    ("6.11", "Место отдыха", "P"),
    ("6.12.1", "Милиция", "М"),
    ("6.12.2", "ГАИ", "ГАИ"),
    ("6.13", "Туалет", "WC"),
    ("6.14", "Пункт контроля автомобильных перевозок", "K"),
    ("6.15", "Достопримечательность", "i"),
    ("6.16", "Пункт обслуживания электронного сбора платы", "€"),
]:
    meanings = {
        "6.3.1–6.3.4": "Указывает заправочную, газовую, зарядную или совмещённую станцию по варианту знака. Проверьте доступный вид топлива или зарядки.",
        "6.11": "Обозначает оборудованное место отдыха и может применяться с табличкой о смотровой канаве. Используйте его для остановки вместо обочины автомагистрали.",
        "6.14": "Указывает пункт контроля перевозок. Выполняйте законные требования уполномоченных лиц и правила остановки.",
        "6.16": "Указывает место обслуживания системы платы за проезд. Не путайте его с полосами свободного проезда.",
    }
    sign(code, name, G6, meanings.get(code, "Информирует о расположении объекта «" + name + "». Расстояние и направление могут уточняться табличками."), symbol=symbol)

sign("7.1.1–7.1.4", "Расстояние до объекта", G7, "Указывает расстояние до опасного участка, начала ограничения или объекта, в том числе расположенного в стороне по варианту таблички.", symbol="m")
sign("7.2.1–7.2.6", "Зона действия", G7, "Указывает протяжённость опасного участка или зону ограничения, её окончание и направление для знаков остановки и стоянки.", symbol="m")
sign("7.3.1–7.3.3", "Направление действия", G7, "Показывает направление действия знака перед перекрёстком или движения к объекту у дороги.", symbol="→")
sign("7.4.1–7.4.11", "Вид транспортного средства", G7, "Ограничивает круг транспорта, на который действует знак. Отдельные таблички выделяют велосипеды, электромобили или исключают их.", symbol="А")
sign("7.5.1", "Субботние, воскресные и праздничные дни", G7, "Ограничивает действие основного знака указанными выходными и праздничными днями.", symbol="S")
sign("7.5.2", "Рабочие дни", G7, "Ограничивает действие основного знака рабочими днями недели. В субботу, воскресенье и официальные праздничные дни ограничение не применяется, но разметка и другие знаки действуют.", symbol="M")
sign("7.5.3", "Дни недели", G7, "Показывает конкретные дни недели, когда применяется основной знак. В остальное время требование знака не действует, однако постоянные ограничения сохраняются.", symbol="Д")
sign("7.5.4–7.5.7", "Время действия", G7, "Указывает часы и, в отдельных вариантах, дни и часы действия знака. Вне периода другие ограничения сохраняются.", symbol="🕒")
sign("7.5.8", "Светлое время суток", G7, "Ограничивает действие знака светлым временем суток. В темноте оценивайте остальные знаки и общие правила.", symbol="☀")
sign("7.5.9", "Тёмное время суток", G7, "Ограничивает действие основного знака тёмным временем суток. Днём требование не применяется, но ночью дополнительно действуют требования к освещению и видимости.", symbol="☾")
sign("7.5.10", "Зимний период", G7, "Указывает, что знак действует с 1 ноября по 31 марта включительно. Не путайте этот период с обязанностью зимних шин с 1 декабря по 1 марта.", symbol="❄")
sign("7.6.1–7.6.18", "Способ постановки транспортного средства на стоянку", G7, "Показывает обязательное положение автомобиля относительно тротуара и проезжей части. Для ряда вариантов стоянка иных видов транспорта запрещена.", symbol="P")
sign("7.7", "Количество опасных поворотов", G7, "Применяется со знаками 1.12.1–1.12.2 и сообщает число последовательных опасных поворотов.", symbol="3")
sign("7.8", "Платные услуги", G7, "Сообщает, что указанная на знаке услуга или стоянка предоставляется за плату. Оплата не отменяет правил стоянки, а неоплаченная парковка может повлечь блокировку колеса или эвакуацию.", symbol="€")
sign("7.9", "Ограничение продолжительности стоянки", G7, "Указывает максимальное время пребывания на стоянке со знаком 5.15. Не превышайте его, переставляя автомобиль в пределах той же зоны без законного основания.", symbol="h")
sign("7.10", "Место для осмотра автомобилей", G7, "Сообщает о смотровой канаве на площадке стоянки или отдыха. Не используйте её как дополнительное парковочное место.", symbol="K")
sign("7.11", "Ограничение максимальной массы", G7, "Распространяет действие основного знака только на транспорт с фактической массой выше указанной.", symbol="т")
sign("7.12", "Нанесение разметки", G7, "Применяется со знаком дорожных работ и предупреждает о нанесении разметки. Возможны свежая краска и изменение сцепления.", symbol="R")
sign("7.13", "Направление главной дороги", G7, "Показывает фактическую траекторию главной дороги со знаками 2.1, 2.4 и 2.5. Изучайте её до выбора направления движения.", symbol="┗")
sign("7.14", "Полоса движения", G7, "Указывает номер полосы, к которой относится светофор или основной знак. Требование действует только на этой полосе, поэтому перестроение меняет применяемое правило.", symbol="↑")
sign("7.15", "Пешеходы — инвалиды по зрению", G7, "Сообщает, что переходом часто пользуются люди с нарушением зрения. Предоставляйте дополнительное время и не подавайте пугающие сигналы.", symbol="П")
sign("7.16", "Влажное покрытие", G7, "Ограничивает действие основного знака периодом влажного покрытия. При сухой дороге общие правила остаются.", symbol="☂")
sign("7.17", "Инвалиды", G7, "Указывает стоянку или её часть для транспорта с опознавательным знаком «Инвалид». Остальным водителям место занимать нельзя.", symbol="И")
sign("7.18", "Кроме инвалидов", G7, "Исключает транспорт с опознавательным знаком «Инвалид» из действия основного ограничения в предусмотренном порядке.", symbol="И")
sign("7.19", "Класс опасного груза", G7, "Указывает конкретный класс опасного груза, для которого применяется запрет знака 3.32. Для остальных грузов ограничение не действует, но общие требования к перевозке сохраняются.", symbol="!")
sign("7.20", "Эвакуатор", G7, "Предупреждает о возможной эвакуации или блокировке колёс при нарушении правил стоянки и отсутствии водителя рядом.", symbol="E")
sign("7.21", "Скользкая полоса наката", G7, "Применяется при дорожных работах и сообщает о разном сцеплении по ширине проезжей части. Избегайте резких манёвров.", symbol="≈")
sign("7.22.1–7.22.4", "Вид опасности", G7, "Применяется вместе со знаком 1.34 и поясняет вероятный вид происшествия: столкновение, опрокидывание, наезд или иное. Табличка помогает заранее выбрать скорость и дистанцию.", symbol="!")
sign("7.23", "Экстренная помощь", G7, "Сообщает о наличии экстренной связи на дороге. При ДТП используйте её для передачи точного места и сведений о пострадавших.", symbol="SOS")
